const data = await browserjs(tabId, () => {
  // Let's get product details specifically
  const details = {};

  // Description and fabric
  const accordions = Array.from(document.querySelectorAll('[data-testid*="accordion"], details, [class*="accordion"]'));
  details.accordions = accordions.map(a => a.innerText);

  // Let's find any text containing fabric percentages or care
  const allElements = Array.from(document.querySelectorAll('p, span, li, div'));
  const fabricMatches = allElements
    .map(e => e.innerText ? e.innerText.trim() : '')
    .filter(t => (t.includes('% Cotton') || t.includes('% Elastane') || t.includes('% Spandex') || t.includes('Signature Stretch')) && t.length < 300);
  details.fabric = Array.from(new Set(fabricMatches));

  // Inseam / rise info
  const measurementMatches = allElements
    .map(e => e.innerText ? e.innerText.trim() : '')
    .filter(t => (t.includes('Inseam') || t.includes('Rise') || t.includes('Leg Opening')) && t.length < 300);
  details.measurements = Array.from(new Set(measurementMatches));

  return details;
});

