  const url = "https://search.brave.com/search?q=" + encodeURIComponent(query);
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const results = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('.snippet[data-type="web"]')).map(el => {
      const a = el.querySelector('a');
      const title = el.querySelector('.title')?.innerText || a?.innerText;
      const desc = el.querySelector('.snippet-description')?.innerText || '';
      return { title, href: a?.href, desc };
    }).filter(x => x.href && !x.href.includes('brave.com'));
  });
  return results;
}

const tests = [
  'Levi\'s women "bootcut" "raw hem" OR "frayed hem"',
  'Wrangler women "bootcut" "raw hem" OR "frayed"',
