const tabId = 1952190319;
const url = "https://www.abercrombie.com/shop/us/p/mid-rise-bootcut-jean-60003357?faceout=model&seq=10";
await tool.navigate({ tabId, url });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const productDetails = await browserjs(tabId, () => {
  // Let's get title, wash names, lengths, sizes, description, composition, reviews
  const h1 = document.querySelector('h1')?.innerText;
  const price = document.querySelector('[data-testid="product-price"], [class*="product-price"], [class*="price"]')?.innerText;

  // lengths
  const lengthButtons = Array.from(document.querySelectorAll('[data-testid*="length"], [aria-label*="Length"], button[id*="length"]')).map(b => b.innerText || b.getAttribute('aria-label'));

  // washes/colors
  const colorSwatches = Array.from(document.querySelectorAll('[data-testid*="color"], [aria-label*="Color"], input[name*="color"]')).map(b => b.getAttribute('aria-label') || b.getAttribute('value') || b.innerText);

  // sizes
  const sizes = Array.from(document.querySelectorAll('[data-testid*="size"], [aria-label*="Waist"], button[name="size"]')).map(b => b.innerText || b.getAttribute('aria-label'));

  return {
    h1,
    price,
    lengthButtons,
    colorSwatches: colorSwatches.slice(0, 10),
    sizes: sizes.slice(0, 15),
    text: document.body.innerText.slice(0, 4000)
  };
