const tabId = 1952190330;

const sites = [
  { name: "Wrangler", url: "https://www.wrangler.com/shop/women-clothing-jeans-bootcut" },
  { name: "Mother Denim", url: "https://www.motherdenim.com/collections/the-bootcut" },
  { name: "Good American", url: "https://www.goodamerican.com/collections/bootcut-jeans" },
  { name: "Paige", url: "https://www.paige.com/c/women/denim/bootcut-flare" },
  { name: "Gap", url: "https://www.gap.com/browse/category.do?cid=3011326" }
];

const results = [];
for (const site of sites) {
  try {
    await tool.navigate({ tabId, url: site.url });
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
    const title = await browserjs(tabId, () => document.title);
    const bodySample = await browserjs(tabId, () => document.body.innerText.slice(0, 300));
    results.push({ name: site.name, url: site.url, title, status: "ok", bodySample: bodySample.replace(/\n+/g, ' ') });
  } catch (e) {
    results.push({ name: site.name, url: site.url, status: "error", error: e.message });
  }
}

console.log("Site accessibility test results:\n", JSON.stringify(results, null, 2));

