  { name: "Revolve", url: "https://www.revolve.com/denim-bootcut/br/174987/" }
];

const accessibility = [];
for (const s of sitesToTest) {
  try {
    await tool.navigate({ tabId, url: s.url });
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 7000 });
    const title = await browserjs(tabId, () => document.title);
    accessibility.push({ name: s.name, title, status: "ok" });
  } catch (e) {
    accessibility.push({ name: s.name, status: "error", error: e.message });
  }
}

console.log("Site accessibility test:", accessibility);

